-- Formato de la CAR: «Cuñentes» pasa a «Cuñetes» (corrección del dueño, 03/11/2026). La plantilla base publica la versión siguiente y la anterior queda retirada.
-- Las copias de las empresas se publican de nuevo con ella (pruebas/demo-car.mjs y demo-dos-sedes-formatos.mjs). No toca personas, empresas, roles ni permisos.
update public.plantillas_versiones v set estado = 'retirada'
from public.plantillas p where v.plantilla_id = p.id and p.empresa_id is null and p.codigo = 'car' and v.estado = 'vigente';
with b as (select id from public.plantillas where empresa_id is null and codigo = 'car'),
r as (select $j${"version":1,"firmas":[{"clave":"inspector","titulo":"Inspector","obligatoria":true,"externo":false,"minimo":1}],"reglas":[{"tipo":"x_en","etiqueta":"No conforme","alcance":"criticos"},{"tipo":"x_en","etiqueta":"No conforme","alcance":"seccion","seccion":"materiales"}],"resultado_defecto":"Conforme","puntaje":false,"na_favorable":true,"hallazgo_vencimiento":false,"observacion_general":true,"secciones":[{"clave":"condicion","titulo":"Condición de la caseta","puntos":[{"clave":"CAR-01","texto":"Pictograma informativo","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"CAR-02","texto":"Acceso libre (sin obstrucciones)","tipo":"cumple","obligatorio":true,"critico":true,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true},{"clave":"CAR-03","texto":"Aspectos generales de la caseta (estructura)","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false}]},{"clave":"materiales","titulo":"Materiales (X = falta o está dañado: por reponer)","puntos":[{"clave":"CAR-M01","texto":"01 Mangueras de nitrilo Ø 2 1/2\"","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"CAR-M02","texto":"02 Mangueras de nitrilo Ø 1 1/2\"","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"CAR-M03","texto":"01 Bifurco válvulado Ø 2 1/2\" a Ø 1 1/2\"","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"CAR-M04","texto":"02 Pitones tipo pistola Ø 1 1/2\" regulable","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"CAR-M05","texto":"01 Pitón tipo pistola Ø 1 1/2\" regulable para espuma","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"CAR-M06","texto":"01 Pitones tipo pistola Ø 2 1/2\" regulable","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"CAR-M07","texto":"02 Cuñetes de AR-AFFF/AFFF","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"CAR-M08","texto":"01 Eductor de espuma de 1 1/2\" regulable con tubo Pick Up","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"CAR-M09","texto":"01 Llave Embon de manguera","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false},{"clave":"CAR-M10","texto":"01 Llave Hidrante","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":false}]}]}$j$::jsonb as receta)
insert into public.plantillas_versiones (plantilla_id, numero, estado, logo, receta, huella, publicado_en)
select b.id, (select coalesce(max(numero), 0) + 1 from public.plantillas_versiones where plantilla_id = b.id), 'vigente', 'positivo', r.receta,
  encode(extensions.digest(convert_to(r.receta::text, 'UTF8'), 'sha256'), 'hex'), now()
from b, r;
update public.plantillas set actualizado_en = now() where empresa_id is null and codigo = 'car';
